    entry("mindfulness-cognitive-therapy", "العلاج المعرفي القائم على اليقظة", "Mindfulness-Based Cognitive Therapy", "برنامج جماعي منظم يدمج ممارسات اليقظة مع فهم أنماط التفكير، ويستخدم خصوصًا للوقاية من الانتكاس لدى بعض المصابين بالاكتئاب المتكرر.", ["ملاحظة الأفكار كأحداث ذهنية", "التعرف المبكر إلى أنماط الانتكاس", "الاستجابة الواعية بدل الطيار الآلي"], ["ممارسات رسمية وغير رسمية", "تمارين معرفية وخطة انتكاس", "ممارسة منزلية ومراجعة جماعية"], ["الوقاية من انتكاس الاكتئاب في سياقات محددة", "برامج جماعية منظمة", "دمج مع متابعة سريرية"], ["اليقظة ليست مناسبة بلا تكييف للجميع", "قد تزيد الضيق مؤقتًا لدى بعض الأشخاص", "لا تستبدل علاج الحالة الحادة أو تقييم الخطر"], ["NICE_DEP", "APA_ETHICS", "COSMIN"]),
    entry("trauma-focused-cbt", "العلاج المعرفي السلوكي المتمركز حول الصدمة", "Trauma-Focused CBT", "تدخلات منظمة لمعالجة اضطراب ما بعد الصدمة تشمل التثقيف والتنظيم والتعرض أو السرد ومعالجة المعاني واستعادة النشاط والأمان.", ["ذكريات الصدمة والتجنب والتهديد الحالي", "المعاني مثل اللوم والعار", "الأمان والدعم والوظيفة"], ["تثقيف ومهارات تنظيم", "معالجة ذاكرة وتعرض متدرج", "تعديل معنى وخطة مستقبل"], ["الأطفال والبالغون وفق بروتوكولات ملائمة", "قد يشمل مقدم رعاية آمنًا", "يستخدم بعد تقييم شامل"], ["لا يبدأ قبل معالجة خطر مستمر", "تفاصيل الصدمة لا تُطلب لمجرد الفضول", "السرعة والتوقيت يحتاجان تعاونًا وموافقة"], ["NICE_PTSD", "WHO_MHGAP", "APA_ETHICS"]),
    entry("emdr", "إزالة التحسس وإعادة المعالجة بحركات العين", "EMDR", "علاج منظم للصدمة يتضمن استحضار جوانب من الذاكرة الصادمة مع تحفيز ثنائي الجانب ضمن بروتوكول متعدد المراحل.", ["الذاكرة المستهدفة والصورة والمعتقد والانفعال", "الاستقرار والموارد قبل المعالجة", "إعادة التقييم والدمج"], ["تاريخ وخطة علاج", "معالجة ذاكرة بتحفيز ثنائي", "تركيب معتقد وتقييم جسدي"], ["موصى به في بعض إرشادات اضطراب ما بعد الصدمة", "يقدمه ممارس مدرب", "قد يدمج مع خطة أوسع"], ["ليس مجرد تحريك عينين", "الأدلة والملاءمة تختلف حسب المشكلة", "الخطر والانفصال والأمراض المصاحبة تحتاج تقييمًا"], ["NICE_PTSD", "APA_ETHICS", "WHO_MHGAP"]),
    entry("motivational-interviewing", "المقابلة التحفيزية", "Motivational Interviewing", "أسلوب تعاوني موجّه يساعد الشخص على استكشاف التردد وتقوية دوافعه وأسبابه الذاتية للتغيير مع احترام الاستقلال.", ["التردد لا المقاومة كصفة", "لغة التغيير والاستمرار", "القيم والثقة والخطوة التالية"], ["أسئلة مفتوحة وتأكيد وانعكاس وتلخيص", "استخلاص لغة التغيير", "خطة عند الاستعداد"], ["السلوكيات الصحية واستخدام المواد والالتزام", "يمكن دمجه مع تدخلات أخرى", "مفيد في اللقاءات القصيرة"], ["ليس تقنية لإقناع الشخص بما يريده المهني", "لا يعالج وحده كل اضطراب", "الخطر الفوري يتطلب إجراء سلامة مباشرًا"], ["WHO_MHGAP", "APA_ETHICS", "COSMIN"]),
    entry("problem-solving-therapy", "علاج حل المشكلات", "Problem-Solving Therapy", "تدخل منظم يحول المشكلات المرهقة إلى أهداف قابلة للعمل، ويعلّم تعريف المشكلة وتوليد البدائل والاختيار والتنفيذ والمراجعة.", ["فصل المشكلة القابلة للحل عن الهم العام", "تقليل التجنب والارتباك", "بناء إحساس بالكفاءة"], ["تعريف محدد وهدف", "عصف بدائل وموازنة", "خطة تنفيذ ومراجعة"], ["الاكتئاب والضغط والرعاية الأولية", "مشكلات صحية واجتماعية عملية", "تدخلات قصيرة أو رقمية مدعومة"], ["لا يحل مشكلة بنيوية بلا موارد", "يجب عدم تحميل الشخص مسؤولية الظلم", "المشاعر والخطر قد تحتاجان تدخلًا إضافيًا"], ["WHO_MHGAP", "NICE_DEP", "APA_ETHICS"]),
    entry("supportive-psychotherapy", "العلاج النفسي الداعم", "Supportive Psychotherapy", "مقاربة مرنة تركز على التحالف والأمان والتثبيت وحل المشكلات وتعزيز الموارد والوظيفة، وقد تستخدم في مراحل شديدة أو معقدة.", ["الاحتياجات الفورية والقدرات المتاحة", "الدعم والتنظيم والروتين", "التكيف والالتزام بالخطة"], ["استماع نشط وتطبيع محسوب", "تثقيف وحل مشكلات", "تنسيق خدمات ومتابعة"], ["أزمات وتكيف ومرض مزمن", "مساندة ضمن علاج متعدد التخصصات", "حفظ الوظيفة وتقليل العزلة"], ["الدعم لا يعني الموافقة على كل تفسير", "يجب أن تبقى الأهداف والحدود واضحة", "الحالات المتخصصة تحتاج إحالة وعلاجًا نوعيًا"], ["WHO_MHGAP", "APA_ETHICS", "WHO_ICF"]),
    entry("play-therapy", "العلاج باللعب", "Play Therapy", "استخدام علاجي منظم للعب والتعبير الرمزي بما يلائم نمو الطفل، لفهم الانفعال والعلاقات وتدريب التنظيم والتواصل.", ["لغة الطفل النمائية وغير اللفظية", "الأمان والعلاقة والتنظيم", "التفاعل مع الوالدين والبيئة"], ["لعب موجّه أو غير موجّه وفق النموذج", "ملاحظة موضوعات وتفاعل", "تدريب والدين وتعميم مهارات"], ["صعوبات انفعالية وسلوكية لدى الأطفال", "التحضير لإجراءات أو تغيرات", "دعم العلاقة بين الطفل ومقدم الرعاية"], ["اللعب العادي ليس علاجًا تلقائيًا", "تفسير الرموز ليس تشخيصًا يقينيًا", "الحماية والإبلاغ والحدود أولوية"], ["APA_ETHICS", "WHO_MHGAP", "COSMIN"]),
    entry("parent-management-training", "تدريب الوالدين على إدارة السلوك", "Parent Management Training", "برامج تعلم مقدمي الرعاية مبادئ التعزيز والروتين والتعليمات والمتابعة وحل المشكلات لتقليل السلوك المعطل وبناء مهارات الطفل.", ["تحديد السلوك والسياق والوظيفة", "زيادة التعزيز الإيجابي والاتساق", "تقليل الصراع والتعليمات الغامضة"], ["ملاحظة وتسجيل بسيط", "نمذجة ولعب أدوار وممارسة منزلية", "خطة تعزيز وعواقب آمنة"], ["مشكلات سلوكية ونمائية متعددة", "برامج فردية أو جماعية", "التنسيق مع المدرسة"], ["ليس تدريبًا على العقاب", "يجب تكييفه للقدرة والثقافة والضغط الأسري", "العنف أو الخطر يحتاج تدخل حماية"], ["WHO_MHGAP", "APA_ETHICS", "WHO_ICF"]),
    entry("parent-child-interaction-therapy", "علاج التفاعل بين الوالد والطفل", "Parent-Child Interaction Therapy", "تدخل سلوكي قائم على تدريب مباشر لمقدم الرعاية أثناء التفاعل مع الطفل لتعزيز العلاقة والمهارات والانضباط الآمن المتسق.", ["جودة التفاعل والانتباه الإيجابي", "تعليمات واضحة ومتابعة", "تعميم المهارة في المنزل"], ["ملاحظة وترميز تفاعل", "تدريب لحظي عبر سماعة أو مشاهدة", "معايير إتقان ومتابعة"], ["مشكلات سلوكية لدى الأطفال الصغار", "دعم العلاقة والتنظيم", "توجد تكييفات لفئات مختلفة"], ["يتطلب تدريبًا متخصصًا وبنية", "لا يستخدم لتجاهل احتياجات حسية أو تواصلية", "سلامة الطفل والعائلة شرط"], ["APA_ETHICS", "WHO_MHGAP", "COSMIN"]),
    entry("schema-therapy", "العلاج بالمخططات", "Schema Therapy", "مقاربة تكاملية تعمل على أنماط راسخة من الاحتياجات غير الملباة والمعتقدات والانفعالات وأساليب المواجهة، وتستخدم علاقة علاجية وتجارب معرفية وسلوكية وخبراتية.", ["المخططات وأساليب المواجهة", "الأوضاع أو الحالات الذاتية", "الاحتياجات والحدود والعلاقات"], ["تصور وصياغة مخطط", "حوار كراسٍ وتصوير ذهني", "تجارب سلوكية وعلاقة علاجية"], ["مشكلات مزمنة وأنماط شخصية معقدة", "قد يستخدم بعد فشل تدخلات أقصر", "يتطلب أهدافًا وقياس نتائج"], ["لغة المخططات ليست حقيقة ثابتة عن الشخص", "التقنيات الخبراتية تحتاج أمانًا وموافقة", "الدليل أقوى لبعض الاستخدامات من غيرها"], ["APA_ETHICS", "COSMIN", "NICE_DEP"]),
    entry("compassion-focused-therapy", "العلاج المتمركز حول التعاطف", "Compassion Focused Therapy", "مقاربة تركز على تطوير قدرة آمنة على التعاطف مع الذات والآخرين، خصوصًا عند العار والنقد الذاتي والتهديد المستمر.", ["أنظمة التهديد والدافع والتهدئة", "النقد الذاتي والعار", "التعاطف كشجاعة وحكمة لا تدليل"], ["تثقيف تطوري ووظائفي", "تخيل وتنفس وصوت متعاطف", "تجارب سلوكية وعلاقات"], ["قد يدمج مع علاجات أخرى", "مشكلات نقد ذاتي ووصم", "برامج فردية وجماعية"], ["التعاطف لا يلغي الحدود أو المساءلة", "قد يثير الخوف لدى من ارتبطت الرعاية عندهم بالأذى", "قوة الدليل تختلف بين الحالات"], ["APA_ETHICS", "COSMIN", "NICE_DEP"]),
    entry("metacognitive-therapy", "العلاج ما وراء المعرفي", "Metacognitive Therapy", "يركز على المعتقدات حول التفكير وعلى نمط القلق والاجترار ومراقبة التهديد ومحاولات السيطرة التي قد تطيل الضيق.", ["المعتقدات الإيجابية والسلبية عن القلق", "متلازمة الانتباه المعرفي", "مرونة توجيه الانتباه"], ["تجارب ميتامعرفية", "تدريب انتباه ووعي منفصل", "تعديل قواعد القلق والاجترار"], ["دُرس في القلق والاكتئاب ومشكلات أخرى", "صيغة منظمة قصيرة نسبيًا", "يحتاج تقييمًا للملاءمة"], ["لا يساوي التفكير في التفكير فقط", "ليست كل توصية إرشادية تعتمد استخدامه", "لا يتجاوز تقييم الخطر والحالات المصاحبة"], ["NICE_GAD", "NICE_PSY", "APA_ETHICS"]),
    entry("narrative-exposure-therapy", "علاج التعرض السردي", "Narrative Exposure Therapy", "علاج متمركز حول الصدمة يبني سردًا زمنيًا للحياة ويربط الذكريات الصادمة بسياقها، وطُوّر خصوصًا للتعرض المتكرر والصدمات المتعددة.", ["خط الحياة والذكريات المتعددة", "التمييز بين الماضي والحاضر", "الشهادة والسياق والكرامة"], ["بناء خط حياة رمزي", "سرد تفصيلي متدرج", "توثيق ومراجعة ودمج"], ["لاجئون وناجون من صدمات متعددة في بعض السياقات", "يمكن تقديمه ضمن خدمات مجتمعية مدربة", "يحتاج خطة أمان ودعم"], ["السرد لا يسبق الأمان", "لا يجوز استخدام الشهادة دون موافقة وخصوصية", "التكييف الثقافي واللغوي ضروري"], ["NICE_PTSD", "WHO_MHGAP", "APA_ETHICS"]),
    entry("interpersonal-social-rhythm-therapy", "العلاج بين الشخصي وتنظيم الإيقاع الاجتماعي", "Interpersonal and Social Rhythm Therapy", "علاج يدمج العمل على العلاقات مع تثبيت الروتين اليومي والنوم والإيقاعات الاجتماعية، ويستخدم خصوصًا ضمن رعاية الاضطراب ثنائي القطب.", ["النوم والروتين والإيقاعات", "تغير الأدوار والنزاعات", "علامات الانتكاس المبكرة"], ["سجل إيقاع اجتماعي", "حل مشكلات بين شخصية", "خطة وقاية وتنسيق دوائي"], ["جزء من علاج شامل للاضطراب ثنائي القطب", "دعم الالتزام والروتين", "تثقيف الأسرة عند الملاءمة"], ["لا يستبدل التقييم الطبي أو الدواء عندما يلزم", "تقليل النوم قد يكون علامة خطر", "الروتين يجب أن يكون واقعيًا لا صارمًا"], ["WHO_MHGAP", "APA_ETHICS", "COSMIN"]),
    entry("contingency-management", "إدارة التعزيز المشروط", "Contingency Management", "تدخل سلوكي يقدم تعزيزًا واضحًا ومحددًا عند تحقق سلوك هدف موثّق، ويستخدم خصوصًا في بعض اضطرابات استخدام المواد.", ["السلوك القابل للقياس", "التعزيز السريع والمتسق", "البدائل والبيئة الداعمة"], ["عقد سلوكي وفحص موضوعي عند الحاجة", "جداول تعزيز", "مراجعة وتدرج نحو تعزيز طبيعي"], ["علاج استخدام المواد ضمن برنامج شامل", "الالتزام بمواعيد أو أدوية في بعض السياقات", "يمكن دمجه مع المقابلة التحفيزية"], ["لا ينبغي أن يكون عقابيًا أو مهينًا", "الحوافز تحتاج عدالة وشفافية", "استمرار التغيير يحتاج موارد تتجاوز البرنامج"], ["WHO_MHGAP", "APA_ETHICS", "COSMIN"]),
