def head(title: str, description: str, canonical: str, schema: dict) -> str:
    payload = json.dumps(schema, ensure_ascii=False).replace("</", "<\\/")
    return f'''<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | مصطلحات علم النفس</title><meta name="description" content="{e(description)}"><meta name="robots" content="index,follow,max-snippet:-1,max-image-preview:large"><link rel="canonical" href="{e(canonical)}"><link rel="alternate" hreflang="ar" href="{e(canonical)}"><link rel="alternate" hreflang="x-default" href="{e(canonical)}"><meta property="og:type" content="article"><meta property="og:site_name" content="مصطلحات علم النفس"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:url" content="{e(canonical)}"><meta name="twitter:card" content="summary_large_image"><style>{STYLE}</style><script type="application/ld+json">{payload}</script></head>'''


def site_header() -> str:
    return f'''<a class="skip" href="#content">انتقل إلى المحتوى</a><header class="site"><div class="wrap head"><a href="{BP}">مصطلحات علم النفس</a><nav class="nav" aria-label="التنقل الرئيسي"><a href="{BP}library/">المكتبة</a><a href="{BP}encyclopedia/">الموسوعة</a><a href="{BP}assessment-lab/">المقاييس</a><a href="{BP}special-needs/">ذوو الاحتياجات الخاصة</a></nav></div></header>'''


def footer() -> str:
    return f'''<footer><div class="wrap"><p><b>مصطلحات علم النفس</b> — معرفة عربية منظمة وقابلة للمراجعة.</p><p>المحتوى تثقيفي. لا يثبت تشخيصًا ولا يختار علاجًا لشخص بعينه. عند وجود خطر مباشر أو تغير حاد استخدم خدمات الطوارئ المحلية أو جهة صحية مؤهلة.</p><p><a href="{BP}trust/">منهج الثقة والمراجعة</a> · <a href="{BP}library/evidence-literacy/">الثقافة العلمية</a></p></div></footer><script>if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('{BP}sw.js').catch(()=>{{}}));</script></body></html>'''


def source_list(ids: list[str]) -> str:
    rows = []
    for sid in ids:
        org, title, url = SOURCES[sid]
        rows.append(f'<li><b>{e(org)}</b>: <a href="{e(url)}" rel="noopener noreferrer">{e(title)}</a> <small>— راجع في {REVIEWED_AT}</small></li>')
    return "".join(rows)


def entry_page(section_slug: str, section: dict, item: dict) -> str:
    canonical = f"{BASE}/library/{section_slug}/{item['slug']}/"
    description = f"دليل عربي منهجي حول {item['title']} ({item['english']}): التعريف، الأسئلة، الأدوات، الاستخدامات، الحدود والمصادر الموثوقة."
    schema = {"@context": "https://schema.org", "@graph": [
        {"@type": "Article", "headline": item["title"], "alternativeHeadline": item["english"], "description": description, "url": canonical, "inLanguage": "ar", "dateModified": REVIEWED_AT, "isPartOf": {"@id": f"{BASE}/library/{section_slug}/#collection"}},
        {"@type": "BreadcrumbList", "itemListElement": [
            {"@type": "ListItem", "position": 1, "name": "الرئيسية", "item": BASE + "/"},
            {"@type": "ListItem", "position": 2, "name": "المكتبة", "item": BASE + "/library/"},
            {"@type": "ListItem", "position": 3, "name": section["title"], "item": f"{BASE}/library/{section_slug}/"},
            {"@type": "ListItem", "position": 4, "name": item["title"], "item": canonical},
        ]},
    ]}
    focus = "".join(f"<li>{e(x)}</li>" for x in item["focus"])
    methods = "".join(f"<li>{e(x)}</li>" for x in item["methods"])
    uses = "".join(f"<li>{e(x)}</li>" for x in item["uses"])
    limits = "".join(f"<li>{e(x)}</li>" for x in item["limits"])
    therapy_note = "<div class=\"notice\"><b>حدود سريرية:</b> إدراج التدخل لا يعني أنه مناسب لكل حالة أو عمر، ولا يجيز تطبيقه دون تدريب أو تقييم أو إشراف مناسب.</div>" if section_slug == "therapies" else ""
    body = f'''<body>{site_header()}<main id="content"><section class="hero"><div class="wrap"><p class="crumbs"><a href="{BP}library/">المكتبة</a> ← <a href="{BP}library/{section_slug}/">{e(section['title'])}</a></p><div class="meta"><span class="tag">مراجعة داخلية</span><span class="tag">المراجعة التالية: {NEXT_REVIEW}</span></div><h1>{e(item['title'])}</h1><p class="english">{e(item['english'])}</p><p class="lead">{e(item['definition'])}</p>{therapy_note}</div></section><div class="wrap layout"><aside class="panel toc"><b>محتويات الصفحة</b><a href="#scope">النطاق والأسئلة</a><a href="#methods">الأدوات والمنهج</a><a href="#uses">الاستخدامات</a><a href="#limits">الحدود والأخطاء</a><a href="#sources">المصادر</a><a href="{BP}library/{section_slug}/">العودة إلى القسم</a></aside><article class="stack"><section class="panel" id="scope"><h2>ما الذي يدرسه أو يستهدفه؟</h2><p>{e(item['definition'])} لا يكفي الاسم وحده لفهم المجال؛ يجب تحديد السؤال والسكان والسياق والهدف والحدود المهنية أو المنهجية.</p><div class="list"><ul>{focus}</ul></div></section><section class="panel" id="methods"><h2>الأدوات والمنهج العملي</h2><p>تُختار الأدوات وفق السؤال، ولا تُجمع لمجرد زيادة البيانات. يجب توثيق الصلاحية واللغة والتدريب والخصوصية وخطة تفسير النتائج.</p><div class="list"><ul>{methods}</ul></div></section><section class="panel" id="uses"><h2>أين يمكن أن يفيد؟</h2><p>تتغير الفائدة بحسب جودة التنفيذ والموارد والتعاون وإمكان الوصول. الاستخدام المؤسسي الجيد يحدد مسؤولًا ومؤشر نتيجة وموعد مراجعة.</p><div class="list"><ul>{uses}</ul></div></section><section class="panel limits" id="limits"><h2>حدود وأخطاء شائعة</h2><p>هذه الحدود ليست تفاصيل هامشية؛ تجاهلها قد يحول المعرفة إلى تضليل أو وصم أو قرار غير عادل.</p><ul>{limits}</ul></section><section class="source-box" id="sources"><h2>مصادر موثوقة للتوسع</h2><ul class="sources">{source_list(item['refs'])}</ul><p><small>المصادر تدعم الإطار العام ولا تعني أن كل سطر اقتباس حرفي أو أن المصدر يقر كل تطبيق محلي. يلزم الرجوع إلى الإرشاد الكامل وأحدث تحديثاته.</small></p></section></article></div></main>{footer()}'''
    page = head(item["title"], description, canonical, schema) + body
    if words(page) < 180:
        raise SystemExit({"entry_too_short": canonical, "words": words(page)})
    return page


def discover_legacy_entries(section_dir: Path, section_slug: str) -> list[dict[str, str]]:
    entries: list[dict[str, str]] = []
    pattern = re.compile(rf"{re.escape(section_slug)}-\d{{2}}")
    for path in sorted(section_dir.glob(f"{section_slug}-*/index.html")):
        route = path.parent.name
        if not pattern.fullmatch(route):
            continue
        source = path.read_text(encoding="utf-8")
        heading = re.search(r"<h1\b[^>]*>(.*?)</h1>", source, flags=re.I | re.S)
        if not heading:
            raise SystemExit(f"Legacy library entry has no H1: {path}")
        title = html.unescape(re.sub(r"<[^>]+>", " ", heading.group(1)))
        title = re.sub(r"\s+", " ", title).strip()
        if not title:
            raise SystemExit(f"Legacy library entry has an empty H1: {path}")
        entries.append({"slug": route, "title": title})
    return entries


def section_page(
    section_slug: str,
    section: dict,
    legacy_entries: list[dict[str, str]] | None = None,
) -> str:
    legacy_entries = legacy_entries or []
    canonical = f"{BASE}/library/{section_slug}/"
    total_entries = len(section["entries"]) + len(legacy_entries)
    description = f"{section['title']}: {total_entries} مدخلًا عربيًا منهجيًا مع تعريفات واستخدامات وحدود ومصادر."
    parts = [{"@type": "Article", "name": item["title"], "url": f"{canonical}{item['slug']}/"} for item in section["entries"]]
    parts.extend(
        {
            "@type": "Article",
            "name": item["title"],
            "url": f"{canonical}{item['slug']}/",
        }
        for item in legacy_entries
    )
    schema = {"@context": "https://schema.org", "@type": "CollectionPage", "@id": canonical + "#collection", "name": section["title"], "description": description, "url": canonical, "inLanguage": "ar", "dateModified": REVIEWED_AT, "hasPart": parts}
    cards = "".join(f'''<article class="card" data-search="{e(item['title'] + ' ' + item['english'] + ' ' + item['definition'])}"><span class="tag">{e(item['english'])}</span><h2>{e(item['title'])}</h2><p>{e(item['definition'])}</p><a class="button" href="{BP}library/{section_slug}/{e(item['slug'])}/">فتح المدخل الكامل</a></article>''' for item in section["entries"])
    legacy_directory = ""
    if legacy_entries:
        links = "".join(
            f'<li><a href="{BP}library/{section_slug}/{e(item["slug"])}/">{e(item["title"])}</a></li>'
            for item in legacy_entries
        )
        legacy_directory = (
            '<section class="wrap panel" data-legacy-library-directory-v353>'
            '<h2>مداخل تأسيسية إضافية</h2>'
            '<p>تضم هذه المجموعة مداخل مستقلة من الإصدار التأسيسي للمكتبة. '
            'أبقينا مساراتها قابلة للوصول وربطناها هنا بدل ترك صفحات معرفية معزولة.</p>'
            f'<ul class="legacy-links">{links}</ul></section>'
        )
    return head(section["title"], description, canonical, schema) + f'''<body>{site_header()}<main id="content"><section class="hero"><div class="wrap"><p class="crumbs"><a href="{BP}library/">المكتبة الأكاديمية</a></p><h1>{e(section['title'])}</h1><p class="lead">{e(section['lead'])}</p><p><b>{total_entries} مدخلًا مستقلاً</b> مع تعريف ونطاق وأدوات واستخدامات وحدود ومصادر.</p><label for="section-search"><b>ابحث داخل القسم</b></label><br><input id="section-search" class="search" type="search" placeholder="اكتب الاسم العربي أو الإنجليزي أو موضوعًا" aria-label="البحث داخل القسم"></div></section><section class="wrap grid" id="cards">{cards}</section>{legacy_directory}</main><script>const q=document.getElementById('section-search'),cards=[...document.querySelectorAll('[data-search]')];q?.addEventListener('input',()=>{{const v=q.value.trim().toLowerCase();cards.forEach(c=>c.hidden=v&&!c.dataset.search.toLowerCase().includes(v));}});</script>{footer()}'''


def library_index() -> str:
    canonical = f"{BASE}/library/"
    total = sum(len(section["entries"]) for section in SECTIONS.values())
    description = f"مكتبة أكاديمية عربية موسعة تضم {total} مدخلًا مستقلاً في فروع علم النفس والعلاجات النفسية ومناهج البحث والقياس، مع مصادر وحدود منهجية."
    schema = {"@context": "https://schema.org", "@type": "CollectionPage", "name": "المكتبة الأكاديمية لعلم النفس", "description": description, "url": canonical, "inLanguage": "ar", "dateModified": REVIEWED_AT, "hasPart": [{"@type": "CollectionPage", "name": section["title"], "url": f"{BASE}/library/{slug}/"} for slug, section in SECTIONS.items()]}
    cards = "".join(f'''<article class="card"><span class="tag">{len(section['entries'])} مدخلًا</span><h2>{e(section['title'])}</h2><p>{e(section['lead'])}</p><a class="button" href="{BP}library/{slug}/">استكشاف القسم</a></article>''' for slug, section in SECTIONS.items())
    return head("المكتبة الأكاديمية لعلم النفس", description, canonical, schema) + f'''<body>{site_header()}<main id="content"><section class="hero"><div class="wrap"><span class="tag">الإصدار {VERSION}</span><h1>المكتبة الأكاديمية لعلم النفس</h1><p class="lead">مرجع عربي منظم يفرق بين المجال العلمي واللقب المهني، وبين وصف العلاج والتوصية الفردية، وبين تصميم الدراسة وقوة الاستنتاج. المحتوى مبني ليُراجع ويُحدّث ويتوسع دون تكرار آلي.</p><div class="notice"><b>عقد الجودة:</b> كل مدخل يشرح التعريف والأسئلة والأدوات والاستخدامات والحدود، ويربط القارئ بمصادر مؤسسية. الحالة الحالية مراجعة داخلية وتحتاج مراجعة خارجية متخصصة قبل اعتمادها كمرجع تدريبي رسمي.</div></div></section><section class="wrap grid">{cards}<article class="card"><span class="tag">أدلة قراءة الدليل</span><h2>الثقافة العلمية</h2><p>أدلة موسعة لقراءة المراجعات المنهجية ويقين الدليل والسببية والإرشادات السريرية.</p><a class="button" href="{BP}library/evidence-literacy/">فتح مكتبة الدليل</a></article></section><section class="wrap panel"><h2>كيف تستخدم المكتبة؟</h2><ol><li>حدد هل تبحث عن تخصص أم تدخل أم تصميم بحث.</li><li>اقرأ الحدود قبل نقل المعلومة إلى قرار.</li><li>افتح المصادر الأصلية وتحقق من تاريخها وسياقها.</li><li>في العلاج والتقييم، استخدم مختصًا مؤهلًا وخطة فردية.</li></ol></section></main>{footer()}'''


def validate() -> dict:
    seen_paths: set[str] = set()
    used_sources: set[str] = set()
    counts: dict[str, int] = {}
    for section_slug, section in SECTIONS.items():
        entries = section["entries"]
        if len(entries) < 20:
            raise SystemExit(f"Section too small: {section_slug}")
        counts[section_slug] = len(entries)
        local: set[str] = set()
        for item in entries:
            slug = item["slug"]
            path = f"{section_slug}/{slug}"
            if not re.fullmatch(r"[a-z0-9-]+", slug) or slug in local or path in seen_paths:
                raise SystemExit(f"Invalid or duplicate slug: {path}")
            local.add(slug)
            seen_paths.add(path)
            if BANNED.search(json.dumps(item, ensure_ascii=False)):
                raise SystemExit(f"Banned terminology: {path}")
            for key in ("focus", "methods", "uses", "limits"):
                if len(item[key]) < 3:
                    raise SystemExit(f"Insufficient depth: {path}/{key}")
            if len(item["refs"]) < 2 or any(ref not in SOURCES for ref in item["refs"]):
                raise SystemExit(f"Invalid sources: {path}")
            used_sources.update(item["refs"])
    for sid, (_, _, url) in SOURCES.items():
        parsed = urlparse(url)
        if parsed.scheme != "https" or not parsed.netloc:
            raise SystemExit(f"Invalid source URL: {sid}")
    return {"counts": counts, "total_entries": sum(counts.values()), "used_sources": len(used_sources)}


def update_sitemap(site: Path, routes: list[str]) -> None:
    ns = "http://www.sitemaps.org/schemas/sitemap/0.9"
    root = ET.Element("urlset", xmlns=ns)
    for route in routes:
        node = ET.SubElement(root, "url")
        ET.SubElement(node, "loc").text = BASE + route
        ET.SubElement(node, "lastmod").text = REVIEWED_AT
        ET.SubElement(node, "changefreq").text = "monthly"
        ET.SubElement(node, "priority").text = "0.80" if route.count("/") <= 3 else "0.68"
    sitemap_name = "sitemap-library-academic-v326.xml"
    ET.ElementTree(root).write(site / sitemap_name, encoding="utf-8", xml_declaration=True)
    index_path = site / "sitemap.xml"
    if not index_path.exists():
        return
    tree = ET.parse(index_path)
    index_root = tree.getroot()
    target = f"{BASE}{sitemap_name}"
    existing = [(node.text or "").strip() for node in index_root.findall("{*}sitemap/{*}loc")]
    if target not in existing:
        node = ET.SubElement(index_root, "sitemap")
        ET.SubElement(node, "loc").text = target
        ET.SubElement(node, "lastmod").text = REVIEWED_AT
        tree.write(index_path, encoding="utf-8", xml_declaration=True)


def publish(site: Path) -> dict:
    contract = validate()
    library = site / "library"
    library.mkdir(parents=True, exist_ok=True)
    (library / "index.html").write_text(library_index(), encoding="utf-8")
    routes = ["/library/"]
    minimum_words = 10**9
    generated = 1
    legacy_counts: dict[str, int] = {}
    for section_slug, section in SECTIONS.items():
        section_dir = library / section_slug
        section_dir.mkdir(parents=True, exist_ok=True)
        legacy_entries = discover_legacy_entries(section_dir, section_slug)
        legacy_counts[section_slug] = len(legacy_entries)
        section_html = section_page(section_slug, section, legacy_entries)
        (section_dir / "index.html").write_text(section_html, encoding="utf-8")
        routes.append(f"/library/{section_slug}/")
        minimum_words = min(minimum_words, words(section_html))
        generated += 1
        for item in section["entries"]:
            page_dir = section_dir / item["slug"]
            page_dir.mkdir(parents=True, exist_ok=True)
            page = entry_page(section_slug, section, item)
            (page_dir / "index.html").write_text(page, encoding="utf-8")
            routes.append(f"/library/{section_slug}/{item['slug']}/")
            minimum_words = min(minimum_words, words(page))
            generated += 1
    update_sitemap(site, routes)
    report = {
        "version": VERSION,
        "status": "passed",
        "review_status": "internally-reviewed-external-specialist-review-required",
        "reviewed_at": REVIEWED_AT,
        "next_review_due": NEXT_REVIEW,
        "sections": contract["counts"],
        "total_entries": contract["total_entries"],
        "generated_pages": generated,
        "legacy_entries_linked": sum(legacy_counts.values()),
        "legacy_entries_by_section": legacy_counts,
        "minimum_page_words": minimum_words,
        "source_registry": len(SOURCES),
        "used_sources": contract["used_sources"],
        "sitemap": "sitemap-library-academic-v326.xml",
    }
    api = site / "api"
    api.mkdir(parents=True, exist_ok=True)
    (api / "academic-library-v326.json").write_text(json.dumps(report, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return report


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("site", type=Path)
    args = parser.parse_args()
    if not args.site.is_dir():
        raise SystemExit(f"Missing site: {args.site}")
    print(json.dumps(publish(args.site.resolve()), ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
